use crate::aap::caps::state_read;

struct Node;

/// Keys the subscription store is consulted under, in order of preference.
const KEYS: &[&str] = &["urls", "subscriptions"];

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        let raw = KEYS.iter().find_map(|k| state_read::get(k));
        let urls = match raw {
            Some(text) => parse_urls(&text),
            None => Vec::new(),
        };
        SubscriptionList { urls }
    }
}

/// Accept either a JSON array of strings or newline-separated text.
fn parse_urls(text: &str) -> Vec<String> {
    let trimmed = text.trim();
    let candidates: Vec<String> = if trimmed.starts_with('[') {
        parse_json_string_array(trimmed).unwrap_or_else(|| parse_lines(trimmed))
    } else {
        parse_lines(trimmed)
    };

    let mut out: Vec<String> = Vec::with_capacity(candidates.len());
    for c in candidates {
        let c = c.trim();
        if c.is_empty() {
            continue;
        }
        if !out.iter().any(|u| u == c) {
            out.push(c.to_string());
        }
    }
    out
}

fn parse_lines(text: &str) -> Vec<String> {
    text.lines()
        .map(str::trim)
        .filter(|l| !l.is_empty() && !l.starts_with('#'))
        .map(String::from)
        .collect()
}

/// A small parser for a JSON array whose elements are all strings.
/// Returns `None` if the text is not of that shape.
fn parse_json_string_array(text: &str) -> Option<Vec<String>> {
    let mut chars = text.chars().peekable();
    let mut out = Vec::new();

    skip_ws(&mut chars);
    if chars.next()? != '[' {
        return None;
    }
    skip_ws(&mut chars);
    if chars.peek() == Some(&']') {
        chars.next();
        skip_ws(&mut chars);
        return if chars.next().is_none() { Some(out) } else { None };
    }

    loop {
        skip_ws(&mut chars);
        if chars.next()? != '"' {
            return None;
        }
        let mut s = String::new();
        loop {
            match chars.next()? {
                '"' => break,
                '\\' => match chars.next()? {
                    '"' => s.push('"'),
                    '\\' => s.push('\\'),
                    '/' => s.push('/'),
                    'b' => s.push('\u{0008}'),
                    'f' => s.push('\u{000C}'),
                    'n' => s.push('\n'),
                    'r' => s.push('\r'),
                    't' => s.push('\t'),
                    'u' => {
                        let mut code: u32 = 0;
                        for _ in 0..4 {
                            code = code * 16 + chars.next()?.to_digit(16)?;
                        }
                        s.push(char::from_u32(code).unwrap_or('\u{FFFD}'));
                    }
                    _ => return None,
                },
                c => s.push(c),
            }
        }
        out.push(s);

        skip_ws(&mut chars);
        match chars.next()? {
            ',' => continue,
            ']' => break,
            _ => return None,
        }
    }

    skip_ws(&mut chars);
    if chars.next().is_some() {
        return None;
    }
    Some(out)
}

fn skip_ws<I: Iterator<Item = char>>(chars: &mut std::iter::Peekable<I>) {
    while matches!(chars.peek(), Some(c) if c.is_whitespace()) {
        chars.next();
    }
}

export!(Node);
